namespace RcsMap {
 public sealed class SurfaceChoice {
  public string Id {get;set;} public string Label {get;set;}
  public override string ToString(){return Label;}
  public static List<SurfaceChoice> All(MapDocument d){var r=new List<SurfaceChoice>{new SurfaceChoice{Id=TerrainGeometry.Ground,Label="地面 · Z=0"}};if(d.Terrain!=null)r.AddRange(d.Terrain.Surfaces.Select(s=>new SurfaceChoice{Id=s.Id,Label=s.Name+" · "+s.Kind}));return r;}
 }
 public class TerrainCanvas:Control {
  public MapDocument Document;public int View=0,SelectedPoint=-1;public string SelectedSurface;
  public Action<int> PointPicked;
  public Action<string> SurfacePicked;
  public Action MoveStarted,MovePreview,MoveFinished;
  public bool DragSurfaces=true,SnapToGrid=true,CarryObjects=true;
  public bool IsMoving {get{return movement!=null;}}
  protected virtual bool BypassSnap {get{return (ModifierKeys&Keys.Shift)!=0;}}
  TerrainMove movement;bool moved;Point dragStart;double dragScale,topScale,topX,topY;
  readonly List<KeyValuePair<string,RectangleF>> surfaceHits=new List<KeyValuePair<string,RectangleF>>();
  double yaw=-35,pitch=30,scale=1;Point last;bool rotate;
  readonly List<KeyValuePair<int,PointF>> hits=new List<KeyValuePair<int,PointF>>();
  public TerrainCanvas(){DoubleBuffered=true;Dock=DockStyle.Fill;TabStop=true;BackColor=Color.FromArgb(245,248,252);}
  public PointF TopScreenPoint(double x,double y){return new PointF((float)(topX+x*topScale),(float)(topY-y*topScale));}
  public void ResetView(){CancelMove();scale=1;yaw=-35;pitch=30;Invalidate();}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Right){CancelMove();return;}if(e.Button!=MouseButtons.Left)return;Focus();last=e.Location;
   foreach(var h in hits.OrderBy(h=>(h.Value.X-e.X)*(h.Value.X-e.X)+(h.Value.Y-e.Y)*(h.Value.Y-e.Y)).ThenBy(h=>TerrainGeometry.Key(Document.Points[h.Key].SurfaceId)==SelectedSurface?0:1))if(Math.Abs(h.Value.X-e.X)<14&&Math.Abs(h.Value.Y-e.Y)<14){SelectedPoint=h.Key;if(PointPicked!=null)PointPicked(h.Key);Invalidate();return;}
   if(View==0){var worldX=(e.X-topX)/topScale;var worldY=(topY-e.Y)/topScale;var candidates=surfaceHits.Where(h=>h.Value.Contains(e.Location)&&TerrainGeometry.Surface(Document,h.Key).Contains(worldX,worldY)).ToList();var selected=candidates.FirstOrDefault(h=>h.Key==SelectedSurface);string id=selected.Key??(candidates.Count>0?candidates.Last().Key:null);if(id!=null){SelectedSurface=id;SelectedPoint=-1;if(SurfacePicked!=null)SurfacePicked(id);if(DragSurfaces&&topScale>0){movement=TerrainMove.Begin(Document,id,CarryObjects);if(movement!=null){dragStart=e.Location;dragScale=topScale;moved=false;Capture=true;Cursor=Cursors.SizeAll;}}Invalidate();}return;}
   if(View==2){rotate=true;Capture=true;}}
  protected override void OnMouseUp(MouseEventArgs e){if(e.Button==MouseButtons.Left&&movement!=null){movement=null;moved=false;Capture=false;Cursor=Cursors.Default;if(MoveFinished!=null)MoveFinished();}rotate=false;Capture=false;base.OnMouseUp(e);}
  public void CancelMove(){if(movement==null)return;movement.Cancel();movement=null;moved=false;Capture=false;Cursor=Cursors.Default;if(MoveFinished!=null)MoveFinished();Invalidate();}
  protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture){rotate=false;CancelMove();}}
  protected override void OnResize(EventArgs e){CancelMove();base.OnResize(e);}
  protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Escape&&IsMoving){CancelMove();e.Handled=e.SuppressKeyPress=true;}base.OnKeyDown(e);}
  protected override void OnMouseMove(MouseEventArgs e){if(movement!=null){int dx=e.X-dragStart.X,dy=e.Y-dragStart.Y;if(!moved&&Math.Abs(dx)<Math.Max(3,SystemInformation.DragSize.Width/2)&&Math.Abs(dy)<Math.Max(3,SystemInformation.DragSize.Height/2))return;if(!moved){moved=true;if(MoveStarted!=null)MoveStarted();}movement.Update(dx/dragScale,-dy/dragScale,SnapToGrid&&!BypassSnap,Document.Settings.Grid);if(MovePreview!=null)MovePreview();Invalidate();}
   else if(rotate){yaw+=(e.X-last.X)*.5;pitch=Math.Max(10,Math.Min(80,pitch+(e.Y-last.Y)*.3));last=e.Location;Invalidate();}base.OnMouseMove(e);}
  protected override void OnMouseWheel(MouseEventArgs e){if(IsMoving)return;scale=Math.Max(.4,Math.Min(2.5,scale*Math.Pow(1.1,e.Delta/120.0)));Invalidate();base.OnMouseWheel(e);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Draw(e.Graphics,ClientRectangle);}
  public void Draw(Graphics g,Rectangle bounds){g.Clear(BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;hits.Clear();surfaceHits.Clear();if(Document==null||bounds.Width<30||bounds.Height<30)return;try{if(View==1)Profile(g,bounds);else Scene(g,bounds);}catch(Exception e){g.DrawString("请修正地形参数："+e.Message,Font,Brushes.Firebrick,15,50);}}
  PointF Raw(double x,double y,double z){if(View==0)return new PointF((float)x,(float)-y);double a=yaw*Math.PI/180,p=pitch*Math.PI/180;return new PointF((float)(x*Math.Cos(a)-y*Math.Sin(a)),(float)(-(x*Math.Sin(a)+y*Math.Cos(a))*Math.Sin(p)-z*Math.Cos(p)));}
  static bool Finite(PointF p){return MapDocument.Finite(p.X)&&MapDocument.Finite(p.Y);}
  public static Color SurfaceColor(TerrainSurface s){return s.Id==TerrainGeometry.Ground?Color.FromArgb(238,242,246):s.Kind==SurfaceKind.水平平台?Color.FromArgb(169,207,234):Color.FromArgb(239,202,137);}
  void Scene(Graphics g,Rectangle b){var d=Document;var all=new List<TerrainSurface>{TerrainGeometry.Surface(d,null)};if(d.Terrain!=null)all.AddRange(d.Terrain.Surfaces);var allraw=new List<PointF>();foreach(var s in all){if(s.Width<=0||s.Depth<=0)continue;allraw.AddRange(Corners(s).Select(c=>Raw(c[0],c[1],c[2])).Where(Finite));}if(allraw.Count==0)return;
   float minx=allraw.Min(p=>p.X),maxx=allraw.Max(p=>p.X),miny=allraw.Min(p=>p.Y),maxy=allraw.Max(p=>p.Y);double k=Math.Min((b.Width-130)/Math.Max(1,maxx-minx),(b.Height-140)/Math.Max(1,maxy-miny))*scale;
   if(View==0){minx=0;maxx=(float)d.Settings.Width;miny=(float)-d.Settings.Height;maxy=0;k=Math.Min((b.Width-130)/Math.Max(1,d.Settings.Width),(b.Height-140)/Math.Max(1,d.Settings.Height))*scale;topScale=k;topX=b.Width/2-d.Settings.Width*k/2;topY=b.Height/2+20+d.Settings.Height*k/2;}
   Func<double,double,double,PointF> screen=(x,y,z)=>{var q=Raw(x,y,z);return new PointF((float)(b.Width/2+(q.X-(minx+maxx)/2)*k),(float)(b.Height/2+20+(q.Y-(miny+maxy)/2)*k));};
   g.DrawString(View==0?"俯视 · 拖动色块移动表面；选中表面优先；Shift暂不吸附 / Esc取消":"三维几何预览 · 拖动旋转视角 / 滚轮缩放",Font,Brushes.SlateGray,12,12);
   g.DrawString("Z为地图规划高度；按真实轮廓检查连接和净空；执行参数须按实车标定",Font,Brushes.SaddleBrown,12,33);
   // Surface centers sorted back-to-front in the current camera, with the ground first.
   foreach(var s in all.OrderBy(s=>s.Id==TerrainGeometry.Ground?Double.MinValue:s.Z0+s.Z1+((s.X+s.Width/2)*Math.Sin(yaw*Math.PI/180)+(s.Y+s.Depth/2)*Math.Cos(yaw*Math.PI/180))*.05)){
    if(s.Width<=0||s.Depth<=0)continue;var poly=Corners(s).Select(c=>screen(c[0],c[1],c[2])).ToArray();if(poly.Any(p=>!Finite(p)))continue;
    if(View==0&&s.Id!=TerrainGeometry.Ground)surfaceHits.Add(new KeyValuePair<string,RectangleF>(s.Id,new RectangleF(poly.Min(p=>p.X),poly.Min(p=>p.Y),poly.Max(p=>p.X)-poly.Min(p=>p.X),poly.Max(p=>p.Y)-poly.Min(p=>p.Y))));
    using(var brush=new SolidBrush(Color.FromArgb(View==0&&s.Id!=SelectedSurface?110:190,SurfaceColor(s))))g.FillPolygon(brush,poly);using(var pen=new Pen(s.Id==SelectedSurface?Color.DarkOrange:Color.SlateGray,s.Id==SelectedSurface?3:1))g.DrawPolygon(pen,poly);
    if(s.Id!=TerrainGeometry.Ground&&(View!=0||s.Id!=SelectedSurface))g.DrawString(s.Name+" · "+s.Z0.ToString("0")+(s.Kind==SurfaceKind.水平平台?"":"→"+s.Z1.ToString("0"))+" mm",Font,Brushes.DarkSlateGray,poly[0]);
   }
   foreach(var o in d.Obstacles){var s=TerrainGeometry.Surface(d,o.SurfaceId);if(s==null)continue;var pts=new[]{screen(o.X,o.Y,s.HeightAt(o.X,o.Y)),screen(o.X+o.Width,o.Y,s.HeightAt(o.X+o.Width,o.Y)),screen(o.X+o.Width,o.Y+o.Height,s.HeightAt(o.X+o.Width,o.Y+o.Height)),screen(o.X,o.Y+o.Height,s.HeightAt(o.X,o.Y+o.Height))};using(var pen=new Pen(Color.IndianRed,2))g.DrawPolygon(pen,pts);}
   for(int i=1;i<d.Points.Count;i++){var a=d.Points[i-1];var c=d.Points[i];TerrainLeg l;string error;bool valid=TerrainGeometry.TryLeg(d,a,c,out l,out error);using(var pen=new Pen(valid?Color.FromArgb(32,111,200):Color.Firebrick,3)){if(!valid)pen.DashStyle=DashStyle.Dash;if(valid)g.DrawLines(pen,TerrainGeometry.Vertices(a,c,l).Select(v=>screen(v[1],v[2],v[3])).ToArray());else g.DrawLine(pen,screen(a.X,a.Y,SafeZ(d,a)),screen(c.X,c.Y,SafeZ(d,c)));}}
   // In top view, selected-surface nodes are drawn last so bridge/ground picks remain explicit.
   foreach(int i in Enumerable.Range(0,d.Points.Count).OrderBy(i=>TerrainGeometry.Key(d.Points[i].SurfaceId)==SelectedSurface?1:0)){
    var p=d.Points[i];double z=SafeZ(d,p);PointF q=screen(p.X,p.Y,z);hits.Add(new KeyValuePair<int,PointF>(i,q));using(var brush=new SolidBrush(i==SelectedPoint?Color.DarkOrange:Color.RoyalBlue))g.FillEllipse(brush,q.X-7,q.Y-7,14,14);g.DrawString("P"+i+" · Z="+z.ToString("0.##"),Font,Brushes.DarkSlateBlue,q.X+10,q.Y+4);
   }
   if(View==0&&SelectedSurface!=null){var surface=TerrainGeometry.Surface(d,SelectedSurface);if(surface!=null&&surface.Id!=TerrainGeometry.Ground){var p=screen(surface.X,surface.Y,0);string text=surface.Name+"  X="+surface.X.ToString("0.##")+"  Y="+surface.Y.ToString("0.##")+" mm";var size=g.MeasureString(text,Font);float tx=Math.Max(8,Math.Min(b.Width-size.Width-8,p.X)),ty=Math.Max(58,Math.Min(b.Height-size.Height-8,p.Y+8));using(var brush=new SolidBrush(Color.FromArgb(235,255,248,220)))g.FillRectangle(brush,tx-3,ty-2,size.Width+6,size.Height+4);g.DrawString(text,Font,Brushes.SaddleBrown,tx,ty);}}
  }
  static double SafeZ(MapDocument d,Waypoint p){double z=TerrainGeometry.Height(d,p);return MapDocument.Finite(z)?z:0;}
  static IEnumerable<double[]> Corners(TerrainSurface s){foreach(var p in SurfaceOutline.Points(s))yield return new[]{p.X,p.Y,s.HeightAt(p.X,p.Y)};}
  void Profile(Graphics g,Rectangle b){var d=Document;g.DrawString("路线侧视 · 横轴为累计水平路程，纵轴为规划高度；竖直比例独立缩放",Font,Brushes.SlateGray,12,12);g.DrawString("点击节点联动归属表。红虚线表示不连通；几何预览不代表实车控制验证。",Font,Brushes.SaddleBrown,12,33);if(d.Points.Count==0)return;
   double[] dist=new double[d.Points.Count];for(int i=1;i<dist.Length;i++){double dx=d.Points[i].X-d.Points[i-1].X,dy=d.Points[i].Y-d.Points[i-1].Y;dist[i]=dist[i-1]+Math.Sqrt(dx*dx+dy*dy);}double topZ=d.Points.Max(p=>SafeZ(d,p));for(int i=1;i<d.Points.Count;i++){TerrainLeg l;string error;if(TerrainGeometry.TryLeg(d,d.Points[i-1],d.Points[i],out l,out error))topZ=Math.Max(topZ,l.Spans.Max(v=>Math.Max(v.Z0,v.Z1)));}double maxz=Math.Max(300,topZ*1.2),length=Math.Max(1,dist.Last());
   Func<double,double,PointF> screen=(x,z)=>new PointF((float)(65+x/length*(b.Width-150)),(float)(b.Height-65-z/maxz*(b.Height-150)));
   using(var pen=new Pen(Color.LightSteelBlue))for(int i=0;i<=4;i++){double z=maxz*i/4;var p=screen(0,z);g.DrawLine(pen,p.X,p.Y,b.Width-35,p.Y);g.DrawString(z.ToString("0")+" mm",Font,Brushes.SlateGray,3,p.Y-10);}
   for(int i=1;i<dist.Length;i++){TerrainLeg leg;string error;bool valid=TerrainGeometry.TryLeg(d,d.Points[i-1],d.Points[i],out leg,out error);using(var pen=new Pen(valid?Color.RoyalBlue:Color.Firebrick,3)){if(!valid)pen.DashStyle=DashStyle.Dash;if(valid)g.DrawLines(pen,TerrainGeometry.Vertices(d.Points[i-1],d.Points[i],leg).Select(v=>screen(dist[i-1]+(dist[i]-dist[i-1])*v[0],v[3])).ToArray());else g.DrawLine(pen,screen(dist[i-1],SafeZ(d,d.Points[i-1])),screen(dist[i],SafeZ(d,d.Points[i])));}
    if(valid){var mid=screen((dist[i-1]+dist[i])/2,(leg.Z0+leg.Z1)/2);g.DrawString("路程 "+leg.Length.ToString("0")+" mm · 坡度 "+leg.MaxSlope.ToString("0.0")+"° · "+leg.Spans.Count+"段 · 限速 "+leg.SpeedLimit.ToString("0")+" mm/s",Font,Brushes.DarkSlateGray,mid.X-35,mid.Y-38);}}
   for(int i=0;i<dist.Length;i++){var p=screen(dist[i],SafeZ(d,d.Points[i]));hits.Add(new KeyValuePair<int,PointF>(i,p));g.FillEllipse(i==SelectedPoint?Brushes.DarkOrange:Brushes.RoyalBlue,p.X-6,p.Y-6,12,12);g.DrawString("P"+i+"\n"+dist[i].ToString("0")+" mm",Font,Brushes.DarkSlateGray,p.X-10,p.Y+10);}
  }
 }
