  void ConfigureGrid(DataGridView grid,Control parent,bool obs){grid.Dock=DockStyle.Fill;grid.AllowUserToAddRows=grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="编号",ReadOnly=true,FillWeight=40});grid.Columns.Add(new DataGridViewComboBoxColumn{HeaderText="所属表面",DisplayMember="Label",ValueMember="Id",FillWeight=130});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="规划Z mm",ReadOnly=true,FillWeight=60});parent.Controls.Add(grid);
